#include "display.h"

// MD E12: generated by tools/make_engine.py. The screen: the selected key's
// machine as the design draws one machine (art.h): its instrument on the left,
// its family's panel on the right, at that key's values (a held step's locks
// included), struck by each note.
namespace mde12 {
inline void display_reset(DisplayState& state) {
    state.hit.initialized = 0;
    state.hit.age = 1 << 20;
}

inline void display(DisplayState& state, const opxy::draw::Input& input, Frame& frame) {
    md::view::begin(frame, input);
    state.hit.update(input);
    const md::view::Moment moment = {state.hit.age, input.reduced_motion};
    const u32 selected = input.model < kit::models ? input.model : 0;
    i32 own[8];
    kit::controls(selected, input.slots, own);
    for (u32 m = 0; m < kit::models; ++m)
        if (m != selected) md::rig::hide_all(frame, art::members, art::machines[m]);
    md::rig::draw(frame, art::parts, art::effects, art::members, art::machines[selected], own, moment,
                  selected == 12 || selected == 14 ? md::rig::shaker : md::rig::drum);
    switch (selected) {
    case 0: md::e12_bd::view(frame, own, moment); break;
    case 1: md::e12_sd::view(frame, own, moment); break;
    case 2: md::e12_ht::view(frame, own, moment); break;
    case 3: md::e12_lt::view(frame, own, moment); break;
    case 4: md::e12_cp::view(frame, own, moment); break;
    case 5: md::e12_rs::view(frame, own, moment); break;
    case 6: md::e12_cb::view(frame, own, moment); break;
    case 7: md::e12_ch::view(frame, own, moment); break;
    case 8: md::e12_oh::view(frame, own, moment); break;
    case 9: md::e12_rc::view(frame, own, moment); break;
    case 10: md::e12_cc::view(frame, own, moment); break;
    case 11: md::e12_br::view(frame, own, moment); break;
    case 12: md::e12_ta::view(frame, own, moment); break;
    case 13: md::e12_tr::view(frame, own, moment); break;
    case 14: md::e12_sh::view(frame, own, moment); break;
    case 15: md::e12_bc::view(frame, own, moment); break;
    default: break;
    }
    // A slot the machine lacks shows nothing (an empty header keeps the stock value).
    for (u32 i = 0; i < 4; ++i)
        if (!kit::model[selected].labels[input.shown[i] & 7u][0])
            opxy::draw::copy(frame.header[i], opxy::draw::header_capacity, " ");
}
}
